<template><main class="simple-auth"><div class="auth-card"><NuxtLink to="/" class="logo">Trove<span>.</span></NuxtLink><div class="icon"><ShieldCheck :size="20" /></div><span class="eyebrow">Проверка</span><h1>Подтвердим контакт</h1><p class="intro">Введите код из сообщения. В production он будет отправляться на вашу почту или телефон.</p><label>Код подтверждения<input v-model="code" class="code" inputmode="numeric" autocomplete="one-time-code" placeholder="Введите код" /></label><p v-if="demoCode" class="demo">Demo-код: <strong>{{ demoCode }}</strong></p><p v-if="error" class="error">{{ error }}</p><button class="submit" :disabled="loading" @click="submit">{{ loading ? 'Проверяем…' : 'Подтвердить' }}</button><NuxtLink to="/auth/login" class="bottom-link">← Вернуться ко входу</NuxtLink></div></main></template>
<script setup lang="ts">
import { ShieldCheck } from '@lucide/vue'
const api=useApi();const code=ref('');const error=ref('');const loading=ref(false);const demoCode=ref('');const type=ref<'EMAIL_VERIFICATION'|'PHONE_VERIFICATION'>('EMAIL_VERIFICATION');onMounted(()=>{type.value=(sessionStorage.getItem('trove_verification_type') as any)||'EMAIL_VERIFICATION';demoCode.value=sessionStorage.getItem('trove_demo_verification_code')||''});const submit=async()=>{loading.value=true;error.value='';try{await api('/api/auth/verify',{method:'POST',body:{code:code.value,type:type.value}});sessionStorage.removeItem('trove_verification_type');sessionStorage.removeItem('trove_demo_verification_code');await navigateTo('/auth/login')}catch{error.value='Код неверный или уже истёк.'}finally{loading.value=false}}</script>

<style scoped lang="scss">.simple-auth{min-height:calc(100vh - 72px);display:grid;place-items:center;padding:55px 20px;background:radial-gradient(circle at 20% 15%,var(--green-soft),transparent 34%),var(--canvas)}.auth-card{width:min(480px,100%);padding:38px;border:1px solid var(--line);border-radius:var(--radius-xl);background:var(--paper);box-shadow:var(--shadow-md)}.logo{display:inline-block;color:var(--ink)!important;text-decoration:none!important;font-family:var(--font-display);font-size:25px;font-weight:900;letter-spacing:-.04em}.logo span{color:var(--brand)}.icon{display:grid;place-items:center;width:46px;height:46px;margin:48px 0 18px;border-radius:14px;background:var(--green-soft);color:var(--green)}.eyebrow{color:var(--green);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.auth-card h1{margin:10px 0 9px;font-family:var(--font-display);font-size:40px;line-height:1;letter-spacing:-.055em}.intro{margin:0;color:var(--muted);font-size:14px;line-height:1.65}.auth-card form{display:grid;gap:16px;margin:28px 0 18px}.auth-card label{font-size:11px;font-weight:900}.auth-card input{display:block;width:100%;height:48px;margin-top:7px;padding:0 13px;border:1px solid var(--line-strong);border-radius:11px;background:var(--paper);color:var(--ink);outline:0}.auth-card input:focus{border-color:var(--brand)}.submit{min-height:50px;border:0;border-radius:11px;background:var(--brand);color:#fff;font-weight:900;cursor:pointer}.submit:disabled{opacity:.55}.error{margin:0;color:var(--danger);font-size:11px}.demo{padding:10px 12px;border-radius:9px;background:var(--surface);font-size:11px}.bottom-link{color:var(--ink)!important;text-decoration:none!important;font-size:11px;font-weight:800}.bottom-link:hover{color:var(--brand-dark)!important}@media(max-width:560px){.auth-card{padding:28px}.icon{margin-top:35px}.auth-card h1{font-size:34px}}</style>